// WebAssets.h - embedded copy of the web/ UI so Smith ships as a single,
// self-contained binary (no sibling files to deploy). The matching WebAssets.cpp
// is GENERATED by tools/gen-web-assets.ps1; regenerate it after editing web/.
//
// The coordinator prefers a web/ directory on disk (dev hot-reload) and falls
// back to these embedded assets when none is present.
//
// Copyright (c) 2026 Red Marmoset Studios Ltd.
#pragma once

#include <cstddef>

namespace Smith
{
    struct WebAsset
    {
        const char* path;            // relative URL path, e.g. "index.html"
        const unsigned char* data;   // raw file bytes (not NUL-terminated)
        size_t size;
        const char* contentType;     // e.g. "text/html; charset=utf-8"
    };

    // Static array of embedded assets, terminated by an entry whose path == nullptr.
    const WebAsset* WebAssets();
    int WebAssetCount();
}
